\set ON_ERROR_STOP on
begin;
set local statement_timeout='10s';
do $guard$
begin
  if to_regclass('public.participant_filters') is null
    or to_regtype('public.filter_resolution_status') is not null
    or to_regclass('private.room_filter_resolutions') is not null
    or to_regprocedure('public.resolve_common_filters(uuid)') is not null
    or exists(select 1 from public.rooms) or exists(select 1 from auth.users) then
    raise exception 'Feature 005 fixture precondition failed';
  end if;
end;
$guard$;

